using System;using System.IO;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Collections.Generic;
class IconBuild {
 static void Main(string[] args){int[] sizes={16,20,24,32,40,48,64,128,256};var images=new List<byte[]>();foreach(int size in sizes){using(var b=new Bitmap(size,size)){using(var g=Graphics.FromImage(b)){g.SmoothingMode=SmoothingMode.AntiAlias;g.ScaleTransform(size/64f,size/64f);g.Clear(Color.Transparent);var shape=new PointF[]{new PointF(5,14),new PointF(25,14),new PointF(31,21),new PointF(59,21),new PointF(59,53),new PointF(5,53)};using(var brush=new SolidBrush(Color.FromArgb(101,224,171)))g.FillPolygon(brush,shape);using(var pen=new Pen(Color.FromArgb(12,16,23),4.5f)){pen.StartCap=LineCap.Square;pen.EndCap=LineCap.Square;g.DrawLines(pen,new PointF[]{new PointF(18,31),new PointF(26,37),new PointF(18,43)});g.DrawLine(pen,34,43,45,43);}}using(var ms=new MemoryStream()){b.Save(ms,ImageFormat.Png);images.Add(ms.ToArray());}if(size==256)b.Save(Path.Combine(args[0],"TrayTidy-icon.png"),ImageFormat.Png);}}
 using(var w=new BinaryWriter(File.Create(Path.Combine(args[0],"TrayTidy.ico")))){w.Write((ushort)0);w.Write((ushort)1);w.Write((ushort)sizes.Length);int offset=6+16*sizes.Length;for(int i=0;i<sizes.Length;i++){w.Write((byte)(sizes[i]==256?0:sizes[i]));w.Write((byte)(sizes[i]==256?0:sizes[i]));w.Write((byte)0);w.Write((byte)0);w.Write((ushort)1);w.Write((ushort)32);w.Write(images[i].Length);w.Write(offset);offset+=images[i].Length;}foreach(var image in images)w.Write(image);}}
}
